-- Payroll + managed-service launch hardening.
ALTER TABLE organizations
  ADD COLUMN IF NOT EXISTS payroll_service_mode varchar(32) NOT NULL DEFAULT 'self_service',
  ADD COLUMN IF NOT EXISTS payroll_annual_divisor numeric(6,2) NOT NULL DEFAULT 365.00,
  ADD COLUMN IF NOT EXISTS statutory_deduction_mode varchar(32) NOT NULL DEFAULT 'split_evenly';

ALTER TABLE payroll_runs
  ADD COLUMN IF NOT EXISTS period_start date,
  ADD COLUMN IF NOT EXISTS period_end date,
  ADD COLUMN IF NOT EXISTS scope_org_unit_id integer REFERENCES org_units(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS calculation_mode varchar(32) NOT NULL DEFAULT 'fixed_salary',
  ADD COLUMN IF NOT EXISTS service_mode varchar(32) NOT NULL DEFAULT 'self_service',
  ADD COLUMN IF NOT EXISTS review_stage varchar(32) NOT NULL DEFAULT 'preparation',
  ADD COLUMN IF NOT EXISTS approved_by_user_id integer REFERENCES users(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS approved_at timestamptz,
  ADD COLUMN IF NOT EXISTS released_by_user_id integer REFERENCES users(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS released_at timestamptz;

-- Historical rows cannot have their true cutoff reconstructed automatically.
-- This conservative backfill keeps the migration deployable; verify old runs before relying on historical reports.
UPDATE payroll_runs
SET period_end = COALESCE(period_end, pay_date),
    period_start = COALESCE(period_start, pay_date)
WHERE period_start IS NULL OR period_end IS NULL;

ALTER TABLE payroll_runs
  ALTER COLUMN period_start SET NOT NULL,
  ALTER COLUMN period_end SET NOT NULL;

CREATE INDEX IF NOT EXISTS payroll_runs_org_period_idx ON payroll_runs (organization_id, period_start, period_end);
CREATE INDEX IF NOT EXISTS payroll_runs_org_scope_idx ON payroll_runs (organization_id, scope_org_unit_id);

ALTER TABLE payroll_runs ALTER COLUMN rule_version SET DEFAULT 'PH-2026.09';
ALTER TABLE payslips ALTER COLUMN rule_version SET DEFAULT 'PH-2026.09';
ALTER TABLE year_end_adjustments ALTER COLUMN rule_version SET DEFAULT 'PH-2026.09';

-- Encryptable government identifiers require room for authenticated envelopes.
alter table employees alter column tin type varchar(180);
alter table employees alter column tin_branch_code type varchar(180);
alter table employees alter column sss_no type varchar(180);
alter table employees alter column philhealth_no type varchar(180);
alter table employees alter column pagibig_no type varchar(180);

alter table data_requests add column if not exists fulfillment_action varchar(64);
alter table data_requests add column if not exists fulfillment_evidence jsonb not null default '{}'::jsonb;
alter table data_requests add column if not exists legal_retention_applied boolean not null default false;

alter table organizations
  add column if not exists statutory_deduction_timing varchar(24) not null default 'split';

alter table employees
  add column if not exists pagibig_voluntary_monthly numeric(10,2) not null default 0;

alter table organizations
  add constraint organizations_statutory_deduction_timing_check
  check (statutory_deduction_timing in ('split', 'first_cutoff', 'second_cutoff'));

alter table contractors add column if not exists tin varchar(180);
alter table contractors add column if not exists withholding_atc varchar(24);
alter table contractors add column if not exists withholding_rate numeric(6,3);

create table if not exists contractor_payments (
  id serial primary key,
  organization_id integer not null references organizations(id) on delete cascade,
  contractor_id integer not null references contractors(id) on delete restrict,
  payment_date date not null,
  gross_amount_php numeric(14,2) not null,
  withholding_atc varchar(24) not null,
  withholding_rate numeric(6,3) not null,
  withholding_amount numeric(14,2) not null,
  net_amount_php numeric(14,2) not null,
  reference varchar(160),
  created_by varchar(120) not null,
  created_at timestamptz not null default now()
);

create index if not exists contractor_payment_org_date_idx on contractor_payments(organization_id, payment_date);
create index if not exists contractor_payment_contractor_idx on contractor_payments(contractor_id);

ALTER TABLE year_end_adjustments
  ADD COLUMN IF NOT EXISTS status varchar(24) NOT NULL DEFAULT 'computed',
  ADD COLUMN IF NOT EXISTS payroll_run_id integer REFERENCES payroll_runs(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS approved_at timestamptz,
  ADD COLUMN IF NOT EXISTS approved_by varchar(120),
  ADD COLUMN IF NOT EXISTS settled_at timestamptz;

CREATE INDEX IF NOT EXISTS year_end_adjustments_run_status_idx
  ON year_end_adjustments (payroll_run_id, status);

CREATE INDEX IF NOT EXISTS year_end_adjustments_org_year_status_idx
  ON year_end_adjustments (organization_id, tax_year, status);

ALTER TABLE "overtime_requests"
  ADD COLUMN IF NOT EXISTS "requested_by_user_id" integer REFERENCES "users"("id") ON DELETE set null,
  ADD COLUMN IF NOT EXISTS "decided_by_user_id" integer REFERENCES "users"("id") ON DELETE set null;
